# Agent: CoreIntegrity.ps1
# Core integrity manifest: SHA-256 of every core file, stored in dependencies\core-manifest.json.
#
# Used by build.ps1, Export-LockedToolkit.ps1, the Client Setup wizard, Test-ClientOverlay.ps1
# and CI to prove that nothing outside client\ was changed. Works without git.
# NOT loaded at toolkit runtime (zero startup cost); only admin tools dot-source this file.
#
#   New-ToolkitCoreManifest   -Root <toolkit folder>   writes the manifest (core maintainers only)
#   Test-ToolkitCoreIntegrity -Root <toolkit folder>   returns @{ Ok; Missing; Modified; Extra; Warnings; ... }
#
# Text files are hashed with CRLF normalized to LF, so a git checkout on Windows (CRLF) and the
# Linux CI (LF) produce the same hashes.

function Get-ToolkitManifestPath {
    param([Parameter(Mandatory)][string]$Root)
    Join-Path $Root 'dependencies/core-manifest.json'
}

function Test-ToolkitPathIsCore {
    # $false for paths that are never core: the client overlay, build output, VCS/editor folders,
    # keys, OS junk, root-level zips, and the manifest itself.
    param([Parameter(Mandatory)][string]$RelativePath)   # forward slashes
    $p = $RelativePath
    if ($p -match '^(client|_builds|\.git|\.claude|\.vscode|\.idea)(/|$)') { return $false }
    if ($p -eq 'dependencies/core-manifest.json') { return $false }
    $leaf = ($p -split '/')[-1]
    if ($leaf -like '*.key' -or $leaf -in '.toolkit-key', '.sfx-key', 'Thumbs.db', 'Desktop.ini', '.DS_Store') { return $false }
    if ($leaf -like '*.swp' -or $leaf -like '*~') { return $false }
    if ($p -notmatch '/' -and $leaf -like '*.zip') { return $false }
    return $true
}

function Get-ToolkitFileHash {
    param([Parameter(Mandatory)][string]$Path)
    $textExt = '.ps1', '.psm1', '.psd1', '.xaml', '.md', '.txt', '.bat', '.cmd', '.json', '.yml', '.yaml', '.sed', '.html', '.htm', '.css', '.js', '.svg', '.gitignore', '.gitattributes', '.code-workspace'
    $ext = [System.IO.Path]::GetExtension($Path).ToLower()
    $name = [System.IO.Path]::GetFileName($Path).ToLower()
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($textExt -contains $ext -or $textExt -contains $name) {
        # normalize CRLF -> LF (Latin-1 maps every byte 1:1, so this is lossless for any encoding)
        $latin1 = [System.Text.Encoding]::GetEncoding(28591)
        $bytes = $latin1.GetBytes($latin1.GetString($bytes).Replace("`r`n", "`n"))
    }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([System.BitConverter]::ToString($sha.ComputeHash($bytes)) -replace '-', '').ToLower() }
    finally { $sha.Dispose() }
}

function Get-ToolkitCoreFiles {
    # Relative (forward-slash) paths of all core files currently on disk, sorted.
    param([Parameter(Mandatory)][string]$Root)
    $Root = (Resolve-Path $Root).Path.TrimEnd('\', '/')
    Get-ChildItem -LiteralPath $Root -Recurse -File -Force -ErrorAction SilentlyContinue |
        ForEach-Object { $_.FullName.Substring($Root.Length + 1).Replace('\', '/') } |
        Where-Object { Test-ToolkitPathIsCore $_ } |
        Sort-Object
}

function New-ToolkitCoreManifest {
    # Writes dependencies\core-manifest.json. Core maintainers only (build.ps1 -UpdateCoreManifest, CI).
    param([Parameter(Mandatory)][string]$Root)
    $Root = (Resolve-Path $Root).Path.TrimEnd('\', '/')
    $version = (Get-Content (Join-Path $Root 'dependencies/version.txt') -Raw -ErrorAction SilentlyContinue)
    $files = [ordered]@{}
    foreach ($rel in Get-ToolkitCoreFiles -Root $Root) {
        $files[$rel] = Get-ToolkitFileHash (Join-Path $Root $rel)
    }
    $manifest = [ordered]@{
        _readme     = 'Generated by build.ps1 -UpdateCoreManifest. Do not edit. Lists every core file; builds refuse to run when a core file differs.'
        CoreVersion = if ($version) { $version.Trim() } else { '0.0.0' }
        Files       = $files
    }
    $json = $manifest | ConvertTo-Json -Depth 4
    [System.IO.File]::WriteAllText((Get-ToolkitManifestPath -Root $Root), ($json -replace "`r`n", "`n") + "`n", (New-Object System.Text.UTF8Encoding $false))
    return $files.Count
}

function Test-ToolkitCoreIntegrity {
    # Compares core files on disk with the manifest.
    #   Ok        : $true when nothing core is missing, modified or added
    #   NoManifest: $true when there is no manifest to check against
    #   Missing / Modified / Extra : relative paths
    #   Warnings  : non-fatal notes (e.g. installers added to dependencies\CustomInstallers)
    param([Parameter(Mandatory)][string]$Root)
    $Root = (Resolve-Path $Root).Path.TrimEnd('\', '/')
    $result = @{ Ok = $false; NoManifest = $false; CoreVersion = $null; Missing = @(); Modified = @(); Extra = @(); Warnings = @() }

    $manifestPath = Get-ToolkitManifestPath -Root $Root
    if (-not (Test-Path -LiteralPath $manifestPath)) { $result.NoManifest = $true; return $result }
    try { $manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json }
    catch { $result.Modified = @('dependencies/core-manifest.json (unreadable)'); return $result }
    $result.CoreVersion = $manifest.CoreVersion

    $expected = @{}
    foreach ($p in $manifest.Files.PSObject.Properties) { $expected[$p.Name] = $p.Value }

    $onDisk = @(Get-ToolkitCoreFiles -Root $Root)
    $diskSet = @{}
    foreach ($rel in $onDisk) { $diskSet[$rel] = $true }

    foreach ($rel in $expected.Keys) {
        if (-not $diskSet.ContainsKey($rel)) { $result.Missing += $rel; continue }
        if ((Get-ToolkitFileHash (Join-Path $Root $rel)) -ne $expected[$rel]) { $result.Modified += $rel }
    }
    foreach ($rel in $onDisk) {
        if ($expected.ContainsKey($rel)) { continue }
        if ($rel -like 'dependencies/CustomInstallers/*') {
            $result.Warnings += "Installer added inside core: $rel - move it to client\CustomInstallers so core updates can't remove it."
        } else {
            $result.Extra += $rel
        }
    }
    $result.Missing  = @($result.Missing | Sort-Object)
    $result.Modified = @($result.Modified | Sort-Object)
    $result.Extra    = @($result.Extra | Sort-Object)
    $result.Ok = ($result.Missing.Count + $result.Modified.Count + $result.Extra.Count) -eq 0
    return $result
}

function Format-ToolkitIntegrityReport {
    # One line per problem, for console and wizard display.
    param([Parameter(Mandatory)][hashtable]$Result)
    $lines = @()
    if ($Result.NoManifest) { return @('No core-manifest.json found - core integrity cannot be checked.') }
    foreach ($f in $Result.Modified) { $lines += "Core file modified: $f" }
    foreach ($f in $Result.Missing)  { $lines += "Core file missing:  $f" }
    foreach ($f in $Result.Extra)    { $lines += "File added outside client\: $f" }
    return $lines
}

function Test-ToolkitBuildOutputPath {
    # Where builds may be written. Returns $null when -Path is allowed, else a reason.
    # Anything inside the toolkit folder (except _builds) would be copied into the next build's payload,
    # so a build could end up shipping its predecessor (and the client folder could ship build output).
    param([Parameter(Mandatory)][string]$Root, [Parameter(Mandatory)][string]$Path)
    if (-not [System.IO.Path]::IsPathRooted($Path)) { return 'Use a full path (for example D:\Builds).' }
    try { $full = [System.IO.Path]::GetFullPath($Path).TrimEnd('\') } catch { return "Not a valid folder path: $Path" }
    $rootFull = [System.IO.Path]::GetFullPath($Root).TrimEnd('\')
    $builds = Join-Path $rootFull '_builds'
    $inside = { param($p, $base) $p -eq $base -or $p.StartsWith("$base\", [System.StringComparison]::OrdinalIgnoreCase) }
    if ((& $inside $full $builds)) { return $null }
    if ((& $inside $full $rootFull)) { return "Builds can't go inside the toolkit folder (only its _builds folder). Pick a folder outside $rootFull." }
    return $null
}

function Assert-ToolkitCoreIntegrity {
    # Build gate used by build.ps1 and Export-LockedToolkit.ps1.
    # Client builds (client\ exists) refuse when core changed, unless -AllowModifiedCore.
    # Core-only checkouts (maintainers) only warn, so day-to-day core development isn't blocked.
    # Returns $true to continue, $false to stop.
    param(
        [Parameter(Mandatory)][string]$Root,
        [switch]$AllowModifiedCore
    )
    $isClient = Test-Path (Join-Path $Root 'client') -PathType Container
    $r = Test-ToolkitCoreIntegrity -Root $Root
    foreach ($w in $r.Warnings) { Write-Host "WARNING: $w" -ForegroundColor Yellow }
    if ($r.Ok) { Write-Host "Core integrity: OK (core v$($r.CoreVersion))" -ForegroundColor Green; return $true }

    $lines = Format-ToolkitIntegrityReport -Result $r
    if (-not $isClient -or $AllowModifiedCore) {
        $why = if ($AllowModifiedCore) { '-AllowModifiedCore' } else { 'core checkout' }
        Write-Host "WARNING: core differs from core-manifest.json ($why - continuing):" -ForegroundColor Yellow
        $lines | Select-Object -First 15 | ForEach-Object { Write-Host "  $_" -ForegroundColor Yellow }
        if (-not $isClient -and -not $r.NoManifest) { Write-Host '  Core maintainers: run .\build.ps1 -UpdateCoreManifest before committing.' -ForegroundColor Yellow }
        return $true
    }
    Write-Host 'BUILD REFUSED: core files differ from the shipped core (only client\ may be changed):' -ForegroundColor Red
    $lines | Select-Object -First 25 | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
    Write-Host '  Restore the original core files (re-extract the core kit, or git checkout upstream), and put customizations in client\.' -ForegroundColor Red
    return $false
}
